using System;
using System.IO;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
using LWS.TruckSports;
using LWS.TruckBowling;
namespace LWS.TruckBaseJumping {
public sealed class BaseJumpSmoke:MonoBehaviour {
#if UNITY_EDITOR || DEVELOPMENT_BUILD
 readonly Stack<IEnumerator> steps=new Stack<IEnumerator>();readonly List<string> records=new List<string>();readonly List<float> samples=new List<float>(20000);BaseJumpMatch m;Keyboard keyboard;InputSettings original,probe;string folder;bool done,error,measure;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Launch(){if(Array.IndexOf(Environment.GetCommandLineArgs(),"-tsBase")<0)return;var g=new GameObject("Base Jumping native physical validation");DontDestroyOnLoad(g);g.AddComponent<BaseJumpSmoke>();}
 void Start(){folder=Path.GetFullPath(Path.Combine(Application.dataPath,"../BaseEvidence"));Directory.CreateDirectory(folder);original=InputSystem.settings;probe=Instantiate(original);probe.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings=probe;keyboard=InputSystem.AddDevice<Keyboard>("Base software keyboard");InputSystem.QueueStateEvent(keyboard,new KeyboardState());Application.logMessageReceived+=Log;steps.Push(Run());}
 void Log(string s,string trace,LogType type){if(type==LogType.Error||type==LogType.Exception){error=true;records.Add("ERROR "+s);}}void Check(bool b,string label){if(!b)throw new Exception(label);records.Add("PASS "+label);Debug.Log("BASE_NATIVE_PASS "+label);}void Note(string label){records.Add(label);Debug.Log("BASE_NATIVE_EVIDENCE "+label);}
 IEnumerator Delay(float seconds){float end=Time.realtimeSinceStartup+seconds;while(Time.realtimeSinceStartup<end)yield return null;}IEnumerator Wait(Func<bool> predicate,float seconds,string label){float end=Time.realtimeSinceStartup+seconds;while(!predicate()){if(Time.realtimeSinceStartup>end)throw new Exception("Timeout "+label+" round="+m.Round+" phase="+m.Phase+" airtime="+m.AirTime+" locks="+m.LandingLocks);yield return null;}}
 void Update(){if(measure)samples.Add(Time.unscaledDeltaTime*1000);if(done)return;try{while(steps.Count>0){var s=steps.Peek();if(!s.MoveNext()){steps.Pop();continue;}if(s.Current is IEnumerator child){steps.Push(child);continue;}return;}Finish(error?2:0);}catch(Exception e){records.Add("FAIL "+e);Debug.LogError(e);Finish(2);}}
 void Finish(int code){done=true;Time.timeScale=1;if(keyboard.added)InputSystem.RemoveDevice(keyboard);InputSystem.settings=original;Destroy(probe);File.WriteAllLines(Path.Combine(folder,"results.txt"),records);Application.Quit(code);}void Capture(string name){ScreenCapture.CaptureScreenshot(Path.Combine(folder,name+".png"));}
 IEnumerator Run(){yield return Delay(.5f);SceneManager.LoadScene("TruckBaseJumping");yield return Delay(.7f);m=FindAnyObjectByType<BaseJumpMatch>();Check(m!=null&&m.jumpers.Length==4,"saved four-payload scene");Screen.SetResolution(1280,720,false);yield return Delay(.4f);
  m.option=0;for(int i=0;i<4;i++)m.setup.players[i].source=BowlingSource.Keyboard;Check(m.StartMatch(),"four injected-keyboard views start");Check(m.ViewCount==4&&!m.Spectating,"four independent human camera mapping");Capture("helicopter-four-720");yield return Wait(()=>m.Phase==BaseJumpPhase.Flight,6,"simultaneous release");for(int i=0;i<4;i++)Check(Mathf.Abs(m.jumpers[i].truck.body.position.y-m.jumpers[0].truck.body.position.y)<.01f,"equal actual release altitude "+i);
  yield return Delay(1);m.Pause();var pos=m.jumpers[0].truck.body.position;var velocity=m.jumpers[0].truck.body.linearVelocity;float age=m.AirTime;yield return Delay(.35f);Check(m.jumpers[0].truck.body.position==pos&&m.jumpers[0].truck.body.linearVelocity==velocity&&m.AirTime==age,"pause preserves freefall and shared wind clock");m.Resume();
  var pad=InputSystem.AddDevice<Gamepad>("Base injected pad");m.setup.players[0].source=BowlingSource.WholeController;Check(m.Assign(0,pad),"injected whole-controller assignment");InputSystem.RemoveDevice(pad);yield return null;Check(m.Paused&&m.menus.Screen==SportsEventScreen.Join,"disconnect during flight opens preserved reconnect modal");Check(m.jumpers[0].truck.body.position==pos,"disconnect freezes unchanged freefall");var replacement=InputSystem.AddDevice<Gamepad>("Base injected replacement");Check(m.Assign(0,replacement),"explicit replacement source accepted");yield return Delay(.2f);m.Resume();m.setup.players[0].source=BowlingSource.Keyboard;m.setup.players[0].pad=null;InputSystem.RemoveDevice(replacement);Time.timeScale=2;
  float deadline=Time.realtimeSinceStartup+95;bool captured=false;while(m.RoundLocks<1){if(Time.realtimeSinceStartup>deadline)throw new Exception("physical deployment variants stalled");if(m.Phase==BaseJumpPhase.Flight){for(int i=0;i<2;i++){var p=m.jumpers[i].truck.body.position;var desired=Vector2.ClampMagnitude(new Vector2(-p.x,-p.z)*.2f,8);float coupling=Mathf.Lerp(.18f,.65f,m.jumpers[i].Opening),power=Mathf.Lerp(3.2f,8.5f,m.jumpers[i].Opening);m.commands[i]=Vector2.ClampMagnitude((desired-new Vector2(m.weatherField.Flow.x,m.weatherField.Flow.z))*coupling/power,1);}for(int i=0;i<3;i++){float h=i==0?210:i==1?95:3;if(!m.jumpers[i].Deployed&&m.jumpers[i].truck.body.position.y<h)m.actions[i]=true;}if(m.jumpers[0].Opening>.99f&&!captured){Time.timeScale=1;Capture("canopies-four-720");captured=true;}}yield return null;}
  Check(m.LandingLocks==4&&m.RoundLocks==1,"four first contacts and one round finalization");Check(m.jumpers[0].Landing.valid&&m.jumpers[1].Landing.valid,"early and normal actual canopy landings safe");Check(!m.jumpers[2].Landing.valid&&!m.jumpers[3].Landing.valid,"too-late and missed deployments physically crash");for(int i=0;i<4;i++)Note("Deployment variant "+i+" "+m.jumpers[i].Outcome+" errorMM="+m.jumpers[i].Landing.errorMillimetres+" timeMS="+m.jumpers[i].Landing.timeMilliseconds+" down="+m.jumpers[i].Landing.verticalSpeed);var locked=m.jumpers[0].Landing;yield return Delay(.4f);Check(m.jumpers[0].Landing.errorMillimetres==locked.errorMillimetres&&m.LandingLocks==4,"post-contact motion cannot improve or repeat scoring");
  for(int humans=1;humans<=4;humans++){m.SetupScreen();for(int i=0;i<4;i++)m.setup.players[i].source=i<humans?BowlingSource.Keyboard:BowlingSource.AI;m.Layout();Check(m.ViewCount==humans&&!m.Spectating,"software layout for "+humans+" humans");for(int i=0;i<humans;i++)Check(m.viewSlots[i]==i&&m.cameras[i].enabled,"view routed to participant "+i+" of "+humans);}
  Screen.SetResolution(1920,1080,false);yield return Delay(.4f);for(int weather=0;weather<3;weather++){m.SetupScreen();m.option=weather;for(int i=0;i<4;i++){m.setup.players[i].source=BowlingSource.AI;m.setup.players[i].difficulty=(BowlingDifficulty)(i%3);}Check(m.StartMatch(),"all-AI weather match "+weather+" starts");Check(m.Spectating&&m.ViewCount==1,"AI-only spectator without controller");Time.timeScale=3;yield return Wait(()=>m.Phase==BaseJumpPhase.Flight,4,"AI release");yield return Delay(2);Capture("weather-"+weather+"-1080");yield return Wait(()=>m.Finished,180,"three-round AI weather match "+weather);Check(m.RoundLocks>=3&&m.LandingLocks==m.RoundLocks*4&&m.Winner>=0,"all AI rounds lock exactly once "+weather);int valid=0;for(int i=0;i<4;i++)if(m.jumpers[i].Landing.valid)valid++;Check(valid>0,"weather preset permits actual safe AI landings "+weather);Note("Weather="+weather+" rounds="+m.RoundLocks+" totals="+string.Join(",",m.totals)+" finalValid="+valid+" winner="+m.Winner);Time.timeScale=1;Capture("result-weather-"+weather);yield return Delay(.2f);}
  m.SetupScreen();for(int i=0;i<4;i++)m.setup.players[i].source=BowlingSource.Keyboard;m.option=2;Check(m.StartMatch(),"four-view rematch configuration preserved");yield return Wait(()=>m.Phase==BaseJumpPhase.Flight,6,"four-view real-time sample");Screen.SetResolution(1920,1080,false);yield return Delay(.4f);Capture("four-1080");measure=true;float end=Time.realtimeSinceStartup+90;while(Time.realtimeSinceStartup<end&&!m.Finished){if(m.Phase==BaseJumpPhase.Flight)for(int i=0;i<4;i++){var j=m.jumpers[i];if(!j.Deployed&&j.truck.body.position.y<200)m.actions[i]=true;var p=j.truck.body.position;var desired=Vector2.ClampMagnitude(new Vector2(-p.x,-p.z)*.2f,8);float coupling=Mathf.Lerp(.18f,.65f,j.Opening),power=Mathf.Lerp(3.2f,8.5f,j.Opening);m.commands[i]=Vector2.ClampMagnitude((desired-new Vector2(m.weatherField.Flow.x,m.weatherField.Flow.z))*coupling/power,1);}yield return null;}measure=false;samples.Sort();float sum=0;foreach(float value in samples)sum+=value;Note("Four-view real-time sample frames="+samples.Count+" meanMS="+(sum/Mathf.Max(1,samples.Count))+" p95="+samples[(int)((samples.Count-1)*.95f)]+" p99="+samples[(int)((samples.Count-1)*.99f)]+" max="+samples[samples.Count-1]+" GPU="+SystemInfo.graphicsDeviceName);Capture("four-canopy-1080");yield return Delay(.2f);SportsNavigation.FrontEnd();yield return Delay(.6f);Check(FindAnyObjectByType<SportsFrontEnd>()!=null,"Base Jumping returns cleanly and scoped weather pipeline restores");}
 void OnDestroy(){Application.logMessageReceived-=Log;}
#endif
}
}
